<script>
  import { onMount } from 'svelte';
  import { api,json } from '../lib/api.js';
  import { bytes } from '../lib/format.js';
  import Dialog from './Dialog.svelte';
  let snapshot=$state(null),draft=$state(null),secrets=$state({}),error=$state(''),message=$state(''),pending=$state(false),checked=$state(null),confirm=$state(false),readOnly=$state(true);
  let disposed=false,controller;
  const fields=[['max_entries','目录读取条目'],['max_page_size','最大每页条目'],['default_page_size','默认每页条目'],['search_max_results','搜索结果条目'],['search_max_examined','搜索检查条目'],['preview_max_bytes','预览上限（字节）'],['upload_max_bytes','上传上限（字节）'],['trash_max_entries','回收站条目'],['copy_max_entries','复制条目'],['copy_max_bytes','复制上限（字节）'],['batch_max_items','批量选择条目']];
  const secretLabels={username:'下载器用户名',password:'下载器密码',tmdb_token:'TMDB 令牌'};
  const payload=()=>({revision:snapshot.revision,settings:JSON.parse(JSON.stringify(draft)),secrets:JSON.parse(JSON.stringify(secrets))});
  const signature=()=>draft?JSON.stringify(payload()):'';
  $effect(()=>{const value=signature();if(checked&&checked.signature!==value)checked=null;});
  async function load(){if(pending)return;pending=true;error='';controller?.abort();controller=new AbortController();try{const [data,overview]=await Promise.all([api('/api/v1/settings',{signal:controller.signal}),api('/api/v1/overview',{signal:controller.signal})]);if(disposed)return;snapshot=data;draft=JSON.parse(JSON.stringify(data.saved));secrets=Object.fromEntries(Object.keys(secretLabels).map(key=>[key,{action:'keep',value:''}]));readOnly=overview.read_only;checked=null;message='';}catch(e){if(!disposed&&e.name!=='AbortError')error=e.message;}finally{if(!disposed)pending=false;}}
  async function validate(){if(pending)return;pending=true;error='';message='';try{const sent=payload();const sig=signature();const result=await api('/api/v1/settings/validate',json('POST',sent));if(disposed)return;checked={signature:sig,request:sent,result};message='校验通过，请核对后保存。保存后需要重启 nasctl 才会应用。';}catch(e){if(!disposed)error=e.message;}finally{if(!disposed)pending=false;}}
  async function save(){if(pending||!checked||checked.signature!==signature())return;pending=true;error='';try{const result=await api('/api/v1/settings',json('POST',checked.request,{headers:{'X-Nasctl-Confirm':'1'}}));if(disposed)return;snapshot=result;draft=JSON.parse(JSON.stringify(result.saved));secrets=Object.fromEntries(Object.keys(secretLabels).map(key=>[key,{action:'keep',value:''}]));checked=null;confirm=false;message='配置已保存。当前服务继续使用原运行值，下次重启生效。';}catch(e){if(!disposed)error=e.message;}finally{if(!disposed)pending=false;}}
  onMount(()=>{load();return()=>{disposed=true;controller?.abort();};});
</script>
<section class="panel settings-section nas-settings" aria-label="统一设备设置">
  <div class="panel-heading"><div><h2>设备配置</h2><p class="muted">校验后保存，下次重启生效。原始 TOML 文件保留。</p></div><button class="button secondary small" disabled={pending} onclick={load}>{draft?'重新读取并放弃草稿':'读取配置'}</button></div>
  {#if error}<p class="notice error" role="alert">{error}</p>{/if}{#if message}<p class="notice success" role="status">{message}</p>{/if}
  {#if snapshot?.restart_required}<p class="notice warning" role="status">已有配置等待重启。这里编辑的是已保存值；当前任务仍按启动时的配置运行。</p>{/if}
  {#if draft}
    <fieldset disabled={pending||readOnly}>
      <details open><summary>存储目录</summary><p class="field-help">只读为默认。开启可写后，操作者才能整理该目录；移除目录配置不会删除文件。路径应先在 NAS 本机准备好。</p>
        {#each draft.storage as root,index}<div class="nas-root-card"><div class="settings-form-grid"><label>目录 ID<input aria-label={'存储目录 ID '+(index+1)} bind:value={root.id} maxlength="32"/></label><label>显示名称<input aria-label={'存储目录名称 '+(index+1)} bind:value={root.label} maxlength="128"/></label><label class="wide">本机绝对路径<input aria-label={'存储目录路径 '+(index+1)} bind:value={root.path} maxlength="1024"/></label></div><div class="nas-root-actions"><label class="checkbox"><input type="checkbox" bind:checked={root.writable}/>允许文件整理</label><label class="checkbox"><input type="checkbox" bind:checked={root.expose_hidden}/>显示隐藏文件</label><button class="text-button danger-text" onclick={()=>draft.storage=draft.storage.filter((_,i)=>i!==index)}>移除目录配置</button></div></div>{/each}
        <button class="button secondary small" disabled={draft.storage.length>=64} onclick={()=>draft.storage=[...draft.storage,{id:'',label:'',path:'',writable:false,expose_hidden:false}]}>添加存储目录</button>
      </details>
      <details><summary>文件预算</summary><div class="settings-form-grid">{#each fields as [key,label]}<label>{label}<input aria-label={label} type="number" min="1" step="1" bind:value={draft.files[key]}/></label>{/each}</div></details>
      <details><summary>追番与下载器</summary><div class="nas-root-actions"><label class="checkbox"><input type="checkbox" bind:checked={draft.anime.enabled}/>启用原生追番</label><label class="checkbox"><input type="checkbox" bind:checked={draft.anime.auto_poll}/>开启定时刷新与同步</label></div><div class="settings-form-grid"><label class="wide">qBittorrent WebUI 地址<input aria-label="下载器地址" bind:value={draft.anime.qbittorrent_url}/></label><label>本地下载目录<input aria-label="本地下载目录" bind:value={draft.anime.download_dir}/></label><label>下载器内部目录<input aria-label="下载器内部目录" bind:value={draft.anime.qbittorrent_download_dir}/></label><label class="wide">媒体库目录<input aria-label="媒体库目录" bind:value={draft.anime.library_dir}/></label><label>RSS 刷新间隔（秒）<input type="number" aria-label="RSS 刷新间隔" min="60" bind:value={draft.anime.poll_interval_seconds}/></label><label>每个订阅读取条目<input type="number" aria-label="RSS 条目上限" min="1" max="500" bind:value={draft.anime.max_items_per_feed}/></label></div>
        {#each Object.entries(secretLabels) as [key,label]}<div class="nas-secret"><label>{label} · {snapshot.secrets[key]?'已设置':'未设置'}<select aria-label={label+'操作'} bind:value={secrets[key].action} onchange={()=>{if(secrets[key].action!=='set')secrets[key].value='';}}><option value="keep">保留现有值</option><option value="set">设置新值</option><option value="clear">清除</option></select></label>{#if secrets[key].action==='set'}<label>新{label}<input aria-label={'新'+label} type="password" autocomplete="new-password" maxlength="4096" bind:value={secrets[key].value}/></label>{/if}</div>{/each}
      </details>
      <details><summary>资源保护与记录</summary><p class="field-help">满足“停止阈值 &lt; 警告阈值 &lt; 开始阈值”，处理组件内存上限不得小于解码预算。Linux cgroup 隔离仍按本机基础配置执行。</p><div class="settings-form-grid">{#each [['start_kb','开始所需可用内存（KiB）'],['warn_kb','内存警告阈值（KiB）'],['stop_kb','内存停止阈值（KiB）'],['worker_high_mb','处理组件内存警告（MiB）'],['worker_max_mb','处理组件内存上限（MiB）']] as [key,label]}<label>{label}<input type="number" min="1" aria-label={label} bind:value={draft.guard_memory[key]}/></label>{/each}{#each [['max_open_jobs','最多开放任务'],['max_history','保留任务记录'],['audit_retention_days','审计保留天数']] as [key,label]}<label>{label}<input type="number" min="1" aria-label={label} bind:value={draft.jobs[key]}/></label>{/each}</div></details>
      <div class="dialog-footer"><button class="button secondary" onclick={validate}>校验配置</button><button class="button primary" disabled={!checked||checked.signature!==signature()} onclick={()=>confirm=true}>保存配置…</button></div>
    </fieldset>
    {#if readOnly}<p class="field-help">当前控制台只读，配置修改不可用。</p>{/if}
    <details class="nas-active"><summary>查看当前运行值</summary><dl class="key-values"><dt>存储目录</dt><dd>{snapshot.active.storage.map(root=>root.label||root.id).join('、')||'未配置'}</dd><dt>上传上限</dt><dd>{bytes(snapshot.active.files.upload_max_bytes)}</dd><dt>复制上限</dt><dd>{bytes(snapshot.active.files.copy_max_bytes)}</dd><dt>原生追番</dt><dd>{snapshot.active.anime.enabled?'启用':'关闭'} · {snapshot.active.anime.auto_poll?'定时调度':'手动调度'}</dd><dt>开放任务上限</dt><dd>{snapshot.active.jobs.max_open_jobs}</dd><dt>任务历史上限</dt><dd>{snapshot.active.jobs.max_history}</dd><dt>处理组件内存上限</dt><dd>{snapshot.active.guard_memory.worker_max_mb} MiB</dd></dl></details>
  {:else if pending}<p class="section-empty" role="status">正在读取配置…</p>{/if}
</section>
{#if confirm&&checked}<Dialog title="保存设备配置" onclose={()=>{if(!pending)confirm=false;}}><p>保存 {checked.request.settings.storage.length} 个存储目录，以及文件、追番和资源预算。已选“清除”的秘密将删除，已选“设置”的值将替换。</p><p class="muted">当前运行任务继续使用原配置。请在任务停止后重启 nasctl，使新目录和预算生效。</p><div class="dialog-footer"><button class="button secondary" disabled={pending} onclick={()=>confirm=false}>返回修改</button><button class="button primary" disabled={pending} onclick={save}>{pending?'正在保存…':'确认保存，下次启动生效'}</button></div>{#if error}<p class="notice error" role="alert">{error}</p>{/if}</Dialog>{/if}
